218	In `src/textstats.js`, replace the line `module.exports = { wordCount, sentenceCount };` with the following block.
219	
220	```javascript
221	// Function words that would otherwise crowd every ranking. The list is
222	// deliberately short and fixed: callers who need a different list can filter
223	// the full ranking (pass a large n) themselves.
224	const STOP_WORDS = new Set([
225	  'a', 'an', 'and', 'are', 'as', 'at', 'be', 'by', 'for', 'from', 'had', 'has',
226	  'have', 'he', 'her', 'his', 'i', 'in', 'is', 'it', 'its', 'of', 'on', 'or',
227	  'she', 'that', 'the', 'their', 'there', 'they', 'this', 'to', 'was', 'were',
228	  'will', 'with',
229	]);
230	
231	/**
232	 * List the most frequent words in a piece of text.
233	 *
234	 * Words are lower-cased, typographic apostrophes are folded to straight ones,
235	 * and stop words are skipped. Entries are ordered by count (highest first),
236	 * then alphabetically, so the result is deterministic.
237	 *
238	 * @param {string} text
239	 * @param {number} n How many entries to return; a non-negative integer.
240	 * @returns {Array<{word: string, count: number}>}
241	 */
242	function topWords(text, n) {
243	  assertText('topWords', text);
244	  if (!Number.isInteger(n) || n < 0) {
245	    throw new RangeError(`topWords: n must be a non-negative integer, received ${String(n)}`);
246	  }
247	  const counts = new Map();
248	  for (const token of tokenize(text)) {
249	    const word = token.toLowerCase().replace(/’/g, "'");
250	    if (STOP_WORDS.has(word)) {
251	      continue;
252	    }
253	    counts.set(word, (counts.get(word) ?? 0) + 1);
254	  }
255	  return [...counts]
256	    .map(([word, count]) => ({ word, count }))
257	    .sort((a, b) => b.count - a.count || (a.word < b.word ? -1 : a.word > b.word ? 1 : 0))
258	    .slice(0, n);
259	}
260	
261	module.exports = { wordCount, sentenceCount, topWords };
262	```
